#include "biglybtc/passive_speed_mapper.hpp"
#include "passive_speed_mapper_literals.hpp"
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <utility>

namespace {
using namespace biglybtc::core;
std::size_t cases=0,assertions=0;
void check(bool value,const char* message){++assertions;if(!value){throw std::runtime_error(message);}}
PassiveSpeedObservation input(std::int64_t time,std::int64_t up=25600,std::int64_t down=51200,std::int64_t rtt=10,bool rebase=false){return {time,up,down,rtt,rebase};}
void append(PassiveSpeedMapper& mapper,PassiveSpeedObservation value){check(bool(mapper.observe(value)),"qualified literal observation rejected");}
PassiveSpeedSnapshot take(const PassiveSpeedMapper& mapper){auto result=mapper.snapshot();check(bool(result),"bounded snapshot failed");return std::move(*result);}
template<std::size_t N>void trace(PassiveSpeedMapper& mapper,const std::array<source_literals::Point,N>& points){std::int64_t now=1;for(const auto& point:points){append(mapper,input(now++,point.up,point.down,point.rtt));const auto snapshot=take(mapper);check(snapshot.history.back().uploadBin==point.x&&snapshot.history.back().downloadBin==point.y&&snapshot.history.back().metric==point.metric,"source trace point mismatch");}}
}
int main(){try{const auto run=[](const char* name,auto body){body();++cases;std::cout<<"case "<<name<<'\n';};
 run("default-empty-state-has-no-runtime-null-limit-or-capacity",[]{PassiveSpeedMapper mapper;const auto value=take(mapper);check(value.state==PassiveSpeedState::Empty&&value.history.empty()&&value.zones.empty()&&!value.upload&&!value.download&&!value.currentMetricRating,"empty mapper fabricated values");check(value.accepted==0&&value.dropped==0&&value.gaps==0&&!value.lastAttempt,"inactive mapper invented an event");});
 run("literal-stable-rates-quantization-zones-and-two-limit-estimates",[]{PassiveSpeedMapper mapper;trace(mapper,source_literals::Stable);const auto value=take(mapper);check(value.history.size()==2&&value.zones.size()==1,"stable actual history size");const auto& zone=value.zones[0];check(zone.uploadStart==12800&&zone.uploadEnd==25855&&zone.downloadStart==25600&&zone.downloadEnd==51455&&zone.metric==0,"source inclusive256-byte zone bounds");check(value.upload&&value.download&&value.upload->bytesPerSecond==25600&&value.download->bytesPerSecond==51200,"largest-good source limits mismatch");check(value.upload->metricRating==1&&value.upload->estimateType==0&&value.upload->hits==1&&value.upload->whenMillis==2,"source estimate metadata mismatch");});
 run("first-observation-never-invents-a-region-or-limit",[]{PassiveSpeedMapper mapper;append(mapper,input(1));const auto value=take(mapper);check(value.history[0].uploadBin==50&&value.history[0].downloadBin==100&&!value.history[0].connectedToPrevious,"first speed must average against source initial0");check(value.currentMetricRating==1&&!value.upload&&!value.download&&value.zones.empty(),"first observation invented a limit");});
 run("source-rate-division-and-adjacent-averaging-precede-expansion",[]{PassiveSpeedMapper mapper;append(mapper,input(1,511,1023,0));append(mapper,input(2,513,1025,0));const auto value=take(mapper);check(value.history[0].uploadBin==0&&value.history[0].downloadBin==1&&value.history[1].uploadBin==1&&value.history[1].downloadBin==3,"rate division/average order changed");check(value.history[0].normalizedRttMillis==1&&value.history[1].normalizedRttMillis==1,"source zero RTT normalization changed");});
 run("actual-zero-inputs-keep-observed-zero-and-source-sub5k-floor",[]{PassiveSpeedMapper mapper;append(mapper,input(1,0,0,0));append(mapper,input(2,0,0,0));const auto value=take(mapper);check(value.history[0].input.uploadBytesPerSecond==0&&value.history[1].input.downloadBytesPerSecond==0,"known actual0 became missing");check(value.upload&&value.download&&value.upload->bytesPerSecond==1&&value.download->bytesPerSecond==1,"source single-bin/null-selection floor lost");check(value.upload->segments.empty()&&value.upload->hits==0&&value.upload->metricRating==1,"source singleton segment policy changed");});
 run("literal-350-to500-rtt-floor-and-rating-boundaries",[]{for(const auto& point:source_literals::Floors){PassiveSpeedMapper mapper;for(std::int64_t i=1;i<=3;++i){append(mapper,input(i,25600,51200,point.rtt));}const auto value=take(mapper);check(value.history.back().metric==point.metric&&value.currentMetricRating==point.rating,"source RTT floor/rating boundary mismatch");}});
 run("literal-three-sample-variance-does-not-divide-deviation-squares",[]{PassiveSpeedMapper mapper;for(unsigned i=0;i<3;++i){append(mapper,input(i+1,25600,51200,10*(i+1)));const auto value=take(mapper);check(value.history.back().metric==source_literals::VarianceMetrics[i],"source variance metric mismatch");}const auto value=take(mapper);check(value.zones.size()==2&&value.zones[0].metric==3&&value.zones[1].metric==10,"region metric integer midpoint mismatch");});
 run("literal-new-bad-region-resets-prior-bin-credit",[]{PassiveSpeedMapper mapper;trace(mapper,source_literals::Choke);const auto value=take(mapper);check(value.currentMetricRating==-1&&value.upload&&value.download,"source choke did not produce current estimates");check(value.upload->bytesPerSecond==25600&&value.download->bytesPerSecond==51200&&value.upload->metricRating==-1&&value.upload->hits==1,"smallest-bad/reset source policy mismatch");check(value.upload->segments.size()==2&&value.upload->segments[1].start==25600&&value.upload->segments[1].end==38400&&value.upload->segments[1].averageMetric==150,"source bad span mismatch");});
 run("source-final-singleton-segment-is-not-silently-repaired",[]{PassiveSpeedMapper mapper;for(std::int64_t i=1;i<=4;++i){append(mapper,input(i,25600,51200,425));}const auto value=take(mapper);check(value.currentMetricRating==0&&value.upload&&value.upload->bytesPerSecond==1&&value.upload->hits==0,"omitted-tail/no-candidate source outcome changed");check(value.upload->metricRating==1&&value.upload->segments.size()==1&&value.upload->segments[0].start==0&&value.upload->segments[0].end==25344,"source final singleton was invented");});
 run("source-clamp-and-signed-short-region-order-remain-visible",[]{PassiveSpeedMapper mapper;const auto maximum=std::numeric_limits<std::int64_t>::max();append(mapper,input(1,maximum,maximum));append(mapper,input(2,maximum,maximum));const auto value=take(mapper);check(value.history[0].uploadBin==32767&&value.history[1].uploadBin==65535,"source quantization/clamp changed");check(value.zones[0].reversedUpload&&value.zones[0].reversedDownload&&value.zones[0].uploadStart==16776960&&value.zones[0].uploadEnd==8388607,"source signed-short inversion normalized away");check(value.upload&&value.upload->bytesPerSecond==8388352,"source inverted-zone estimate endpoint changed");});
 run("explicit-rebase-resets-rtt-window-but-retains-source-speed-continuity",[]{PassiveSpeedMapper mapper;for(std::int64_t i=1;i<=3;++i){append(mapper,input(i,25600,51200,500));}append(mapper,input(4,51200,102400,10,true));const auto value=take(mapper);check(value.history.back().metric==0&&value.history.back().uploadBin==150&&value.history.back().connectedToPrevious&&value.gaps==0,"source rebase altered speed/history continuity");check(value.zones.back().metric==75&&value.currentMetricRating==1,"source rebase mixed old RTT samples");});
 run("missing-negative-and-clock-events-break-current-without-fake-history",[]{PassiveSpeedMapper mapper;trace(mapper,source_literals::Stable);const auto past=take(mapper);auto missing=input(3);missing.rttMillis.reset();auto result=mapper.observe(missing);check(!result&&result.error()==PassiveSpeedError::Missing,"missing observation accepted");auto value=take(mapper);check(value.state==PassiveSpeedState::Gap&&value.history==past.history&&!value.upload&&!value.currentMetricRating,"gap erased or invented observations");result=mapper.observe(input(4,-1));check(!result&&result.error()==PassiveSpeedError::Invalid,"negative rate accepted");result=mapper.observe(input(4));check(!result&&result.error()==PassiveSpeedError::Clock,"duplicate observation time accepted");append(mapper,input(5));value=take(mapper);check(value.history.size()==3&&!value.history.back().connectedToPrevious&&value.history.back().uploadBin==50&&!value.upload&&value.zones.size()==1,"recovery joined across missing measurements");append(mapper,input(6));value=take(mapper);check(value.history.back().connectedToPrevious&&value.zones.size()==2&&value.upload&&value.gaps==3,"real recovery did not restore bounded source estimates");});
 run("checked-original-int-variance-overflow-is-an-explicit-gap",[]{PassiveSpeedMapper mapper;append(mapper,input(1,25600,51200,1));append(mapper,input(2,25600,51200,65535));auto value=take(mapper);check(value.history.back().metric==46339,"source finite int variance boundary mismatch");const auto result=mapper.observe(input(3,25600,51200,1));check(!result&&result.error()==PassiveSpeedError::Overflow,"unsafe source int overflow was treated as good0");value=take(mapper);check(value.state==PassiveSpeedState::Overflow&&value.history.size()==2&&!value.upload&&!value.currentMetricRating&&value.lastAttempt->rttMillis==1,"overflow invented/removed observations");append(mapper,input(4));value=take(mapper);check(!value.history.back().connectedToPrevious&&!value.upload,"overflow gap was bridged");});
 run("source-oversized-rtt-normalizes-only-within-original-int-domain",[]{PassiveSpeedMapper mapper;append(mapper,input(1,25600,51200,65536));auto value=take(mapper);check(value.history[0].normalizedRttMillis==1500&&value.history[0].input.rttMillis==65536,"source >65535 RTT normalization/raw retention lost");const auto result=mapper.observe(input(2,25600,51200,std::numeric_limits<std::int64_t>::max()));check(!result&&result.error()==PassiveSpeedError::Overflow,"out-of-source-int RTT silently narrowed");});
 run("original1200-history-eviction-discards120-oldest-points",[]{PassiveSpeedMapper mapper;for(std::int64_t i=1;i<=1201;++i){append(mapper,input(i));}const auto value=take(mapper);check(value.accepted==1201&&value.dropped==120&&value.history.size()==1081&&value.zones.size()==1080,"source 10percent eviction changed");check(value.history.front().input.observedMillis==121&&!value.history.front().connectedToPrevious&&value.history.back().input.observedMillis==1201,"source oldest-first retention/zone edge changed");check(value.upload&&value.upload->bytesPerSecond==25600&&value.upload->hits==1080,"retained source estimator/history hits mismatch");});
 run("snapshots-own-raw-inputs-and-time-comparisons-never-overflow",[]{PassiveSpeedMapper mapper;trace(mapper,source_literals::Stable);auto first=take(mapper);append(mapper,input(std::numeric_limits<std::int64_t>::max()));check(first.history.size()==2&&first.upload->whenMillis==2,"old snapshot aliased new observations");first.history[0].metric=65535;const auto actual=take(mapper);check(actual.history[0].metric==0&&actual.history.back().input.observedMillis==std::numeric_limits<std::int64_t>::max(),"owned snapshot edited mapper or lost full timestamp");const auto result=mapper.observe(input(std::numeric_limits<std::int64_t>::min()));check(!result&&result.error()==PassiveSpeedError::Clock,"negative/wrapped timestamp admitted");check(take(mapper).history.size()==3,"clock failure created a synthetic observation");});
 std::cout<<"PASS "<<cases<<" passive-speed-mapper cases; "<<assertions<<" assertions; explicit observations only; source-derived literals, no Java/runtime equality credit\n";return 0;
}catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}}
